import { withAuth } from "@workos-inc/authkit-nextjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Upserts a WorkOS-authenticated user into the local user store, keyed by the
// WorkOS user id. This is the seam between AuthKit sessions and app data.
function syncUser(input: { id: string; email: string; name: string }): User {
  const existing = users.find((u) => u.id === input.id);
  if (existing) {
    existing.email = input.email;
    existing.name = input.name;
    return existing;
  }

  const created: User = { ...input, createdAt: new Date().toISOString().slice(0, 10) };
  users.push(created);
  return created;
}

// Reads the signed-in user from the AuthKit session (if any) and syncs it
// into the local user store.
export async function getCurrentUser(): Promise<User | undefined> {
  const { user } = await withAuth();
  if (!user) return undefined;

  const name = [user.firstName, user.lastName].filter(Boolean).join(" ") || user.email;
  return syncUser({ id: user.id, email: user.email, name });
}

