import { authkitMiddleware } from "@workos-inc/authkit-nextjs";

// Next.js 16 renamed middleware.ts to proxy.ts; this is what gates /dashboard
// for signed-out visitors (redirecting them into the AuthKit sign-in flow).
// "/" stays public so the marketing page still renders when signed out.
export default authkitMiddleware({
  middlewareAuth: {
    enabled: true,
    unauthenticatedPaths: ["/"],
  },
});

export const config = { matcher: ["/", "/dashboard/:path*"] };

